ins:=jsonb_build_object('company_id',sel->0->>'company_id','security_id','synthetic','listing_episode_id','synthetic','ticker','TEST','listing_start','2026-08-01T00:00:00Z','listing_end',NULL,'eligible_common_equity',true,'security_type','CS','links_evidence',jsonb_build_object('source_refs',jsonb_build_array('SYNTHETIC_SHAPE_ONLY')));
