SELECT details->'input_versions'||jsonb_build_object('scope_sha256',ctl->>'scope_sha256','ctx06_bundle_sha256',population_top3000_202608_202609_v1.ctx06_practical_bundle_sha_v2()) INTO versions FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=35325;
BEGIN PERFORM population_top3000_202608_202609_v1.ctx06_release_ingest_v3(NULL,body,versions,NULL);RAISE EXCEPTION 'MISSING_CLAIM_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CTX06_V3_EXACT_CURRENT_UNRELEASED_CLAIM_REQUIRED' THEN RAISE;END IF;END;
