bad:=body||jsonb_build_object('fixture_only',false,'full_period_verified',true,'window_start','2026-08-01','window_end','2026-09-30','evidence_semantics','QUALIFIED_DATED_INSTRUMENT_INTERVALS_WITH_EXPLICIT_LIFECYCLE_COVERAGE_V2');
versions:=versions||jsonb_build_object('instrument_manifest_sha256',encode(sha256(convert_to(bad::text,'UTF8')),'hex'));
