prospective:=population_top3000_202608_202609_v1.population_recovery_manifest_v1();
SELECT jsonb_object_agg(proname,encode(sha256(convert_to(pg_get_functiondef(oid),'UTF8')),'hex')) INTO hashes FROM pg_proc WHERE pronamespace='population_top3000_202608_202609_v1'::regnamespace AND proname IN('ctx06_release_shape_v3','ctx06_release_ingest_v3');
