SELECT jsonb_build_object('a',to_jsonb(ac),'p',to_jsonb(pc),'manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1(),'release_count',(SELECT count(*) FROM population_top3000_202608_202609_v1.ctx06_practical_release_v2),'old_task',(SELECT to_jsonb(t) FROM population_top3000_202608_202609_v1.pipeline_task t WHERE task_id='467735a6-c132-4678-b853-242383a738f9'),'adapters',(SELECT jsonb_agg(to_jsonb(pa) ORDER BY stage) FROM population_top3000_202608_202609_v1.pipeline_adapter pa WHERE family_id='CTX06')) INTO after_state FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton;
